// The package's public facade. It defines nothing itself: every export it
// advertises is re-exported from a sibling file INSIDE THIS SAME installed
// package (RWF-004a).
//
// `vulnerable` takes the multi-hop route (index -> internal/middle -> lib);
// `safe` takes the direct one, and must never be confused with it.
var middle = require("./internal/middle");
var lib = require("./lib");

// A same-name export re-exported from a DIFFERENT installed package. The
// name matches this package's own `vulnerable` exactly, which is the
// coincidence a name-based binding would fall for. Chasing it is
// cross-package re-export (RWF-004b), deliberately NOT implemented, so this
// must stay unattributed rather than binding to other-lib's function.
var elsewhere = require("other-lib");

module.exports = {
  vulnerable: middle.vulnerable,
  safe: lib.safe,
  fromOtherPackage: elsewhere.vulnerable,
};
